1026	+
1027	+public class EventServiceTests
1028	+{
1029	+    private static AppDbContext CreateContext(string dbName)
1030	+    {
1031	+        var options = new DbContextOptionsBuilder<AppDbContext>()
1032	+            .UseInMemoryDatabase(dbName)
1033	+            .Options;
