1037	+    [Fact]
1038	+    public async Task GetEventsAsync_ReturnsEventsSortedByZeitpunktWithVenueName()
1039	+    {
1040	+        using var dbContext = CreateContext(nameof(GetEventsAsync_ReturnsEventsSortedByZeitpunktWithVenueName));
1041	+
1042	+        var venue = new Venue { Id = Guid.NewGuid(), Name = "Stadthalle Nordpark" };
1043	+        var room = new Room { Id = Guid.NewGuid(), Name = "Kleiner Saal", VenueId = venue.Id };
1044	+        dbContext.Venues.Add(venue);
1045	+        dbContext.Rooms.Add(room);
1046	+
1047	+        var laterEvent = new Event
1048	+        {
1049	+            Id = Guid.NewGuid(),
1050	+            Titel = "Später",
1051	+            Beschreibung = "b",
1052	+            DauerMinuten = 60,
1053	+            Altersfreigabe = 0,
1054	+            Zeitpunkt = new DateTime(2026, 10, 1, 20, 0, 0, DateTimeKind.Unspecified),
1055	+            VenueId = venue.Id,
1056	+            RoomId = room.Id
1057	+        };
1058	+        var earlierEvent = new Event
1059	+        {
1060	+            Id = Guid.NewGuid(),
1061	+            Titel = "Früher",
1062	+            Beschreibung = "b",
1063	+            DauerMinuten = 60,
1064	+            Altersfreigabe = 0,
1065	+            Zeitpunkt = new DateTime(2026, 9, 1, 19, 0, 0, DateTimeKind.Unspecified),
1066	+            VenueId = venue.Id,
1067	+            RoomId = room.Id
1068	+        };
1069	+        dbContext.Events.AddRange(laterEvent, earlierEvent);
1070	+        await dbContext.SaveChangesAsync();
1071	+
1072	+        var service = new EventService(dbContext);
1073	+        var result = await service.GetEventsAsync();
1074	+
1075	+        Assert.Equal(2, result.Count);
1076	+        Assert.Equal("Früher", result[0].Title);
1077	+        Assert.Equal("Später", result[1].Title);
1078	+        Assert.Equal("Stadthalle Nordpark", result[0].VenueName);
1079	+    }
1080	+}
