1092	+public class SeedImporterTests
1093	+{
1094	+    private static AppDbContext CreateContext(string dbName)
1095	+    {
1096	+        var options = new DbContextOptionsBuilder<AppDbContext>()
1097	+            .UseInMemoryDatabase(dbName)
1098	+            .Options;
1099	+        return new AppDbContext(options);
1100	+    }
1101	+
1102	+    [Fact]
1103	+    public async Task ImportAsync_OnEmptyDatabase_ImportsVenuesRoomsAndEvents()
1104	+    {
1105	+        using var dbContext = CreateContext(nameof(ImportAsync_OnEmptyDatabase_ImportsVenuesRoomsAndEvents));
1106	+
1107	+        await SeedImporter.ImportAsync(dbContext, AppContext.BaseDirectory);
1108	+
1109	+        Assert.Equal(2, await dbContext.Venues.CountAsync());
1110	+        Assert.Equal(4, await dbContext.Rooms.CountAsync());
1111	+        Assert.Equal(6, await dbContext.Events.CountAsync());
1112	+
1113	+        var e1 = await dbContext.Events
1114	+            .Include(e => e.Venue)
1115	+            .Include(e => e.Room)
1116	+            .SingleAsync(e => e.Titel == "Kammerkonzert Frühling");
1117	+
1118	+        Assert.Equal("Stadthalle Nordpark", e1.Venue!.Name);
1119	+        Assert.Equal("Kleiner Saal", e1.Room!.Name);
1120	+    }
1121	+
